\label{MainResultIntro}
    Let $G$ be a countably infinite amenable group and let $\mathcal{F} = (F_n)_{n = 1}^\infty$ be a left-F\o lner sequence. Given a measure preserving system $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ and a $f \in L^\infty(X,\mu)$, there exists a bounded sequence of complex numbers $(c_g)_{g \in G} \subseteq \text{range}(f)$ satisfying

    \begin{alignat*}{2}
        &\lim_{n\rightarrow\infty}\frac{1}{|F_n|}\sum_{g \in F_n}c_g = \int_Xfd\mu, \lim_{n\rightarrow\infty}\frac{1}{|F_n|}\sum_{g \in F_n}c_{hg}\overline{c_g} = \langle \tau_hf,f\rangle\text{ for all }h \in G\text{, and}\\
        &\lim_{n\rightarrow\infty}\frac{1}{|F_n|}\sum_{g \in F_n}d_{h_1g,1}^{t_1}d_{h_2g,2}^{t_2}\cdots d_{h_\ell g,\ell}^{t_\ell} = \int_X\tau_{h_1}f_1^{t_1}\tau_{h_2}f_2^{t_2}\cdots \tau_{h_\ell}f_\ell^{t_\ell} d\mu,
    \end{alignat*}
    where $\ell,t_i \in \mathbb{N}$, $h_i \in G$, $(d_{g,i})_{g \in G} \in \left\{(c_g)_{g \in G},(\overline{c_g})_{g \in G}\right\}$, $f_i \in \{f,\overline{f}\}$, and $(d_{g,i})_{g \in G} = (c_g)_{g \in G}$ if and only if $f_i = f$.

\label{EquivalentCharacterizationsOfvdC}
    For $V \subseteq \mathbb{N}$, the following are equivalent:
    \begin{enumerate}[(i)]
        \item\label{UniformDistributionvdC} $V$ is a vdC set.

        \item\label{boundedcomplexvdC} For any sequence $(u_n)_{n = 1}^\infty$ of complex numbers of modulus 1, if

        \begin{equation}
            \lim_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^Nu_{n+v}\overline{u_n} = 0\text{, for all }v \in V\text{, then }\lim_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^Nu_n = 0.
        \end{equation}

        \item\label{cesaroboundedcomplexvdc} For any sequence $(u_n)_{n = 1}^\infty$ of complex numbers satisfying

        \begin{equation}
            \limsup_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^N|u_n|^2 < \infty\text{ and }\lim_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^Nu_{n+v}\overline{u_n} = 0\text{ for all }v \in V,
        \end{equation}
        we have

        \begin{equation}
            \lim_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^Nu_n = 0.
        \end{equation}

        \item\label{cesaroboundedhilbertvdc} For any Hilbert space $\mathcal{H}$ and any sequence $(\xi_n)_{n = 1}^\infty$ of vectors in $\mathcal{H}$ satisfying

        \begin{equation}
            \limsup_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^N||\xi_n||^2 < \infty\text{ and }\lim_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^N\langle \xi_{n+v}, \xi_n\rangle = 0\text{ for all }v \in V,
        \end{equation}
        we have

        \begin{equation}
            \lim_{N\rightarrow\infty}\left|\left|\frac{1}{N}\sum_{n = 1}^N\xi_n\right|\right| = 0.
        \end{equation}

        \item\label{MPSvdC} For any measure preserving system $(X,\mathscr{B},\mu,\tau)$ and any $f \in L^2(X,\mu)$ satisfying $\langle \tau^vf,f\rangle = 0$ for all $v \in V$, we have $\int_Xfd\mu = 0$.

        \item\label{operatorialrecurrencevdc} $V$ is a \textbf{set of operatorial recurrence}, i.e., if $\mathcal{H}$ is a Hilbert space, $U:\mathcal{H}\rightarrow\mathcal{H}$ is a unitary operator, and $\xi \in \mathcal{H}$ satisfies $\langle U^v\xi,\xi\rangle = 0$ for all $v \in V$, then $P_I\xi = 0$, where $P_I:\mathcal{H}\rightarrow\mathcal{H}$ is the orthogonal projection onto the subspace of $U$-invariant vectors.

        \item\label{operatorialrecurrencevdc+Kronecker} If $\mathcal{H}$ is a Hilbert space, $U:\mathcal{H}\rightarrow\mathcal{H}$ is a unitary operator, and $\xi \in \mathcal{H}$ satisies $\langle U^v\xi,\xi\rangle = 0$ for all $v \in V$, then $P_\mathcal{K}\xi = 0$, where $P_\mathcal{K}:\mathcal{H}\rightarrow\mathcal{H}$ is the orthogonal projection onto the smallest closed subspace of $\mathcal{H}$ containing all eigenvectors of $U$.
    \end{enumerate}

