\label{FinitizedConvergenceInMeasure}
    Let $G$ be an amenable group, $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ an ergodic measure preserving system, and let $f \in L^1(X,\mu)$. Given $\epsilon > 0$ there exists a finite $K \subseteq G$ and a $\delta > 0$ such that for any $(K,\delta)$-invariant probability measure $\nu$ on $G$, there exists a set $A \in \mathscr{B}$ with $\mu(A) > 1-\epsilon$ such that for all $x \in A$ we have

    \begin{equation}\label{ConvergenceInMeasureEquation1}
        \left|\int_Gf(\tau_gx)d\nu(g)-\int_Xfd\mu\right| < \epsilon.
    \end{equation}
    Furthermore, if $f \in L^\infty(X,\mu)$, then we can choose $A$ so that for all $x \in A$ we also have

    \begin{equation}\label{ConvergenceInMeasureEquation2}
        \sup_{g \in \text{supp}(\nu)}|f(\tau_gx)| \ge ||f||_\infty-\epsilon.
    \end{equation}

We begin with the case in which $f \in L^1(X,\mu)$. Let $K_1 \subseteq K_2 \subseteq \cdots \subseteq G$ be an exhaustion of $G$ by finite sets, and let $\delta_1 > \delta_2 > \cdots > \delta_n > \cdots$ tend to $0$. Let us assume for the sake of contradiction that there exists some $\epsilon > 0$ such that for each $n \in \mathbb{N}$ there exists a set $A_n \in \mathscr{B}$ with $\mu(A_n) > \epsilon$ and a $(K_n,\delta_n)$-invariant probability measure $\nu_n$ on $G$ such that

    \begin{equation}
        \left|\int_Gf(\tau_gx)d\nu_n(g)-\int_Xfd\mu\right| > \epsilon
    \end{equation}
    for all $x \in A_n$. Since $(\nu_n)_{n = 1}^\infty$ is a Reiter sequence, the Mean Ergodic Theorem (see, e.g. \cite[Proposition 5.4]{AmenabilityByPaterson}) tells us that

    \begin{equation}
        \lim_{n\rightarrow\infty}\int_Gf(\tau_gx)d\nu_n(g) = \int_Xfd\mu,
    \end{equation}
    with convergence taking place in $L^1(X,\mu)$. In particular, we have convergence in measure, so let $N \in \mathbb{N}$ be such that for all $n \ge N$ we have

    \begin{equation}
        \left|\int_Gf(\tau_gx)d\nu_n(g)-\int_Xfd\mu\right| < \epsilon
    \end{equation}
    on a set of measure at least $1-\epsilon$, which yields the desired contradiction.

    Now let us assume that $f \in L^\infty(X,\mu)$. Let $A_0 \in \mathscr{B}$ be such that $\mu(A_0) > 1-2^{-1}\epsilon$, and Equation \eqref{ConvergenceInMeasureEquation1} is satisfied for $\frac{\epsilon}{2}, f$ and all $x \in A_0$. For each $p \in \mathbb{N}$, let $A_p \in \mathscr{B}$ be such that $\mu(A_p) > 1-2^{-p-1}\epsilon$, and Equation \eqref{ConvergenceInMeasureEquation1} is satisfied for $2^{-p-1}\epsilon, |f|^p$ and all $x \in A_p$. Let $A = \bigcap_{p = 0}^\infty A_p$. We see that for any $x \in A$ and any $p \in \mathbb{N}$, there exists $g \in \text{supp}(\nu)$ for which $|f(\tau_gx)| > ||f||_p-\epsilon$. The desired result follows from the fact that $||f||_\infty = \lim_{p\rightarrow\infty}||f||_p$.

\label{Ruzsa'sResult}
    Let $\phi:\mathbb{Z}\rightarrow\mathbb{C}$ be a positive definite sequence satisfying $\phi(0) = 1$. There exists $(c_n)_{n = 1}^\infty \subseteq \mathbb{S}^1$ for which

    \begin{equation}
        \phi(h) = \lim_{N\rightarrow\infty}\frac{1}{N}\sum_{n = 1}^N c_{n+h}\overline{c_n}.
    \end{equation}

\label{KeyLemmaForAmenableGroups}
   Let $G$ be a countably infinite amenable group, let $H \subseteq G$ be finite with $e \in H$, let $\epsilon > 0$ be arbitrary, and let $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ be a measure preserving system. Fix $f \in L^2(X,\mu)$ and let $R \subseteq \text{Range}(f)$ be a dense subset. There exists a $\delta > 0$, a finite set $K \subseteq G$, and a sequence $(c_g)_{g \in G} \subseteq R$ with $||(c_g)_{g \in G}||_\infty$ bounded by a function of $f$ and $\epsilon$, such that for every $(K,\delta)$-invariant probability measure $\nu$ we have

   \begin{alignat}{2}
       &\int_G|c_g|^2d\nu(g) \overset{\epsilon}{=} ||f||_2^2,\ \int_Gc_gd\nu(g) \overset{\epsilon}{=} \int_Xfd\mu,\text{ and }\label{KeyLemmaEquation1}\\
       &\int_Gc_{hg}\overline{c_g}d\nu(g) \overset{\epsilon}{=} \langle \tau_hf,f\rangle\text{ for all }h \in H.\label{KeyLemmaEquation2}
   \end{alignat}
   Furthermore, if $f \in L^\infty(X,\mu)$, then for any $h_1,\cdots,h_\ell \in H$ and $t_1,\cdots,t_\ell \in [0,|H|]$ we have

   \begin{alignat}{2}
       &\int_Gd_{h_1g,1}^{t_1}\cdots d_{h_\ell g,\ell}^{t_\ell}d\nu(g) \overset{\epsilon}{=} \int_X \tau_{h_1}f_1^{t_1}\cdots \tau_{h_\ell}f_\ell^{t_\ell}d\mu\text{, and}\label{KeyLemmaEquation3}\\
       &||(d_{h_1g,1}^{t_1}\cdots d_{h_\ell g,\ell}^{t_\ell})_{g \in G}||_\infty \overset{\epsilon}{=} ||\tau_{h_1}f_1^{t_1}\cdots \tau_{h_\ell}f_\ell^{t_\ell}||_\infty,\label{KeyLemmaEquation4}
   \end{alignat}
   where $f_i \in \{f,\overline{f}\}$ and $(d_{g,i})_{g \in G} \in \left\{(c_g)_{g \in G},(\overline{c}_g)_{g \in G}\right\}$, and $f_i = f$ if and only if $(d_{g,i})_{g \in G} = (c_g)_{g \in G}$.

\label{RepresentationTheoremForAmenableGroups}
   Let $G$ be a countably infinite amenable group, let $(\nu_n)_{n = 1}^\infty$ be a Reiter sequence, and let $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ be a measure preserving system. Given $f \in L^2(X,\mu)$ and a dense set $R \subseteq \text{Range}(f)$, there exists a sequence of complex numbers $(c_g)_{g \in G}$ taking values in $R$ satisfying

   \begin{alignat}{2}
       &\lim_{n\rightarrow\infty}\int_G|c_g|^2d\nu_n = ||f||_2^2,\ \lim_{n\rightarrow\infty}\int_Gc_gd\nu_n = \int_Xfd\mu,\text{ and }\label{FvdCIsvdCEquation1}\\
       &\lim_{n\rightarrow\infty}\int_Gc_{hg}\overline{c_g}d\nu_n = \langle \tau_hf,f\rangle\text{ for all }h \in G.\label{FvdCIsvdCEquation2}
   \end{alignat}
   Furthermore, if $f \in L^\infty(X,\mu)$, then for any $h_1,\cdots,h_\ell \in G$ and $t_1,\cdots,t_\ell \in \mathbb{N}$ we have

   \begin{alignat}{2}
       &\lim_{n\rightarrow\infty}\int_Gd_{h_1g,1}^{t_1}\cdots d_{h_\ell g,\ell}^{t_\ell}d\nu_n = \int_X \tau_{h_1}f_1^{t_1}\cdots \tau_{h_\ell}f_\ell^{t_\ell}d\mu\text{, and}\label{FvdCIsvdCEquation3}\\
       &||(d_{h_1g,1}^{t_1}\cdots d_{h_\ell g,\ell}^{t_\ell})_{g \in G}||_\infty = ||\tau_{h_1}f_1^{t_1}\cdots \tau_{h_\ell}f_\ell^{t_\ell}||_\infty,\label{FvdCIsvdCEquation4}
   \end{alignat}   
   where $f_i \in \{f,\overline{f}\}$ and $(d_{g,i})_{g \in G} \in \left\{(c_g)_{g \in G},(\overline{c}_g)_{g \in G}\right\}$, and $f_i = f$ if and only if $(d_{g,i})_{g \in G} = (c_g)_{g \in G}$.

\label{Modulus1RepresentationForAbelianGroups}
    Let $G$ be a countably infinite abelian group and let $
u$ be a probability measure on $\widehat{G}$. Let $S(G) \subseteq \mathbb{S}^1$ be the smallest closed set that contains the range of all characters of $G$. There exists a measure preserving system $\mathcal{X} := (X,\mathscr{B},\mu,(	au_g)_{g \in G})$ and a measurable $f:Xightarrow S(G)$ for which $\hat{
u}(h) = \langle 	au_hf,fangle$ and $
u(\{0\}) = \int_Xfd\mu$. Furthermore, the maximal spectral type of $\mathcal{X}$ is $\sum_{n \in \mathbb{Z}}
u_n$, where $
u_n(E) = 
u(\{x \in \widehat{G}\ |\ x^n \in E\})$.

Let $X = \widehat{G}\times S(G)$, let $\mathscr{B}$ be the Borel $\sigma$-algebra, let $\tau:X\rightarrow X$ be given by $\tau_g(\chi,x) = (\chi,\chi(g)x)$, and let $\mu = \nu\times m$, where $m$ is the normalized Haar measure of the compact group $S(G)$. Let $f(\chi,x) = x$ if $\chi \neq e_{\widehat{G}}$, and $f(e_{\widehat{G}},x) = 1$. We see that

    \begin{alignat*}{2}
        &\langle \tau_hf,f\rangle = \int_{\widehat{G}}\int_{S(G)}\chi(h)dm(x)d\nu(\chi) = \int_{\widehat{G}}\chi(h)d\nu(\chi) = \hat{\nu}(h) = \phi(h)\text{, and}\\
        &\int_Xfd\mu = \int_{\widehat{G}}\int_{S(G)}f(\chi,x)dm(x)d\nu(\chi) = \int_{\widehat{G}}\mathbbm{1}_{e_{\widehat{G}}}(\chi)d\nu(\chi) = \nu(\{0\}).
    \end{alignat*}
    It only remains to show that the maximal spectral type of $\mathcal{X}$ is of the given form. Since $X$ is a compact abelian group, the characters of $X$ have a dense span in $L^2(X,\mu)$, so it suffices to show that the spectral measure of each character is some $\nu_n$. We note that $S(G)$ is either a finite set, or it is $\mathbb{T}$, so any character on $S(G)$ is of the form $x\mapsto x^s$ for some $s \in \mathbb{Z}$. Let $g \in G = \widehat{\widehat{G}}$ and $s \in \mathbb{Z}$ both be arbitrary, let $f'(\chi,x) = \chi(g)x^s$, and observe that

    \begin{equation}
        \langle \tau_hf',f'\rangle = \int_{\widehat{G}\times S(G)}\chi(g)(\chi(h)x)^s\overline{\chi(g)x^s}d\mu(\chi,x) = \int_{\widehat{G}\times S(G)}\chi(h)^sd\mu(\chi,x) = \hat{\nu}_s(h).
    \end{equation}

\label{FvdCIsvdCForAmenableGroups}
    Let $G$ be a countably infinite amenable group, let $(\nu_n)_{n = 1}^\infty$ be a Reiter sequence, and let $V \subseteq G$. Items (i)-(iii) are equivalent, items (iv) and (v) are equivalent, and if $G$ is abelian, then items (i)-(v) are equivalent.
    \begin{enumerate}[(i)]
        \item For any sequence $(u_g)_{g \in G}$ of complex numbers satisfying

        \begin{alignat}{2}
            &\limsup_{n\rightarrow\infty}\int_G|u_g|^2d\nu_n(g) < \infty,\quad \sup_{h \in G}\limsup_{n\rightarrow\infty}\left|\int_G(u_{hg}-u_g)d\nu_n(g)\right| = 0\text{, and }\label{ComplexNumbersSequenceEquation1}\\
            &\lim_{n\rightarrow\infty}\int_Gu_{vg}\overline{u_g}d\nu_n(g) = 0,
        \end{alignat}
        for all $v \in V$, we have

        \begin{equation}
            \lim_{n\rightarrow\infty}\int_Gu_gd\nu_n(g) = 0.
        \end{equation}

        \item For any separable Hilbert space and any sequence $(\xi_g)_{g \in G} \subseteq \mathcal{H}$ of vectors satisfying

        \begin{alignat}{2}
            &\limsup_{n\rightarrow\infty}\int_G||\xi_g||^2d\nu_n(g) < \infty,\quad \sup_{h \in G}\limsup_{n\rightarrow\infty}\left|\left|\int_G(\xi_{hg}-\xi_g)d\nu_n(g)\right|\right| = 0\text{, and }\label{HilbertSpaceSequenceEquation1}\\
            &\lim_{n\rightarrow\infty}\int_G\langle\xi_{vg},\xi_g\rangle d\nu_n(g) = 0,\label{HilbertSpaceSequenceEquation2}
        \end{alignat}
        for all $v \in V$, we have

        \begin{equation}
            \lim_{n\rightarrow\infty}\left|\left|\int_G\xi_gd\nu_n(g)\right|\right| = 0.
        \end{equation}

        \item For any measure preserving system $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ and any $f \in L^2(X,\mu)$ satisfying $\langle \tau_vf,f\rangle = 0$ for all $v \in V$, we have $\int_Xfd\mu = 0$.

        \item For any sequence $(u_g)_{g \in G} \subseteq \mathbb{S}^1$ satisfying

        \begin{equation}
            \lim_{n\rightarrow\infty}\int_Gu_{vg}\overline{u_g}d\nu_n(g) = 0,\text{ for all }v \in V,\text{ we have }\lim_{n\rightarrow\infty}\int_Gu_gd\nu_n(g) = 0.
        \end{equation}

        \item For any measure preserving system $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ and any $f:X\rightarrow\mathbb{S}^1$ satisfying $\langle \tau_vf,f\rangle = 0$ for all $v \in V$, we have $\int_Xfd\mu = 0$.
    \end{enumerate}

We first show that (iii)$\rightarrow$(ii). Let us assume for the sake of contradiction that Equations \eqref{HilbertSpaceSequenceEquation1}-\eqref{HilbertSpaceSequenceEquation2} are satisfied, but there is some $(M_q)_{q = 1}^\infty \subseteq \mathbb{N}$ for which

\begin{equation}
    \lim_{q\rightarrow\infty}\frac{1}{M_q}\left|\left|\int_G\xi_gd\nu_{M_q}(g)\right|\right| = \epsilon > 0.
\end{equation}
Let $S_{h,q} = \int_G\xi_{h^{-1}g}d\nu_{M_q}(g)$ and let $\xi_{g,q} = \xi_g-S_{e,q}$. By replacing $(M_q)_{q = 1}^\infty$ with a subsequence, we may assume without loss of generality that

\begin{alignat*}{2}
    &\gamma_1(h) := \lim_{q\rightarrow\infty}\int_G\langle\xi_{h^{-1}g},\xi_g\rangle d\nu_{M_q}(g)\text{ and }\gamma_2(h) := \lim_{q\rightarrow\infty}\int_G\langle \xi_{h^{-1}g,q},\xi_{g,q}\rangle d\nu_{M_q}(g)
\end{alignat*}
exist for all $h \in G$. To see that $(\gamma_1(h))_{h \in G}$ is a positive definite sequence, we see that for any $g_1,\cdots,g_n \in G$ and any $c_1,\cdots,c_n \in \mathbb{C}$, we have

\begin{alignat*}{2}
&\sum_{i,j = 1}^nc_i\overline{c_j}\gamma(g_j^{-1}g_i) = \sum_{i,j = 1}^nc_i\overline{c_j}\lim_{q\rightarrow\infty}\int_G\langle \xi_{g_i^{-1}g_jg},\xi_g\rangle d\nu_{M_q}(g) = \sum_{i,j = 1}^nc_i\overline{c_j}\lim_{q\rightarrow\infty}\int_G\langle \xi_{g_i^{-1}g},\xi_{g_j^{-1}g}\rangle d\nu_{M_q}(g)\\
=&\lim_{q\rightarrow\infty}\int_G\langle\sum_{i = 1}^nc_i\xi_{g_i^{-1}g},\sum_{j = 1}^nc_j\xi_{g_j^{-1}g} d\nu_{M_q}(g) \ge 0.
\end{alignat*}
A similar calculation shows that $(\gamma_2(h))_{h \in G}$ is also a positive definite sequence.
Using the second assumption in Equation \eqref{HilbertSpaceSequenceEquation1}, we see that

\begin{alignat*}{2}
    \gamma_2(h)&= \lim_{q\rightarrow\infty}\int_G\langle \xi_{h^{-1}g}-S_{e,q},\xi_g-S_{e,q}\rangle d\nu_{M_q}(g)\\
    &= \gamma_1(h)+\lim_{q\rightarrow\infty}\left(-\int_G\langle S_{e,q},\xi_g\rangle d\nu_{M_q}(g)-\int_G\langle \xi_{h^{-1}g},S_{e,q}\rangle d\nu_{M_q}(g)+\int_G\langle S_{e,q},S_{e,q}\rangle d\nu_{M_q}(g)\right)\\
    &= \gamma_1(h)+\lim_{q\rightarrow\infty}\left(-\langle S_{e,q},S_{e,q}\rangle -\langle S_{h,q},S_{e,q}\rangle+\langle S_{e,q},S_{e,q}\rangle\right) = \gamma_1(h)-\epsilon^2.
\end{alignat*}
We now use the equivalence of items \eqref{GeneralMPSvdC} and \eqref{MeanOnAPFunctionsCharacterization1} in Theorem \ref{EquivalentCharacterizationsInCountableGroups}. Letting $M$ denote the unique invariant mean on the set $W(G)$ of weakly almost periodic functions on $G$, we see that $\gamma_1(v) = \overline{\gamma_1(v^{-1})} = 0$ for all $v \in V$, so $M(\gamma_1) = 0$. It follows that $M(\gamma_2) = -\epsilon^2 < 0$, but this contradicts the fact that $M(\phi) \ge 0$ whenever $\phi$ is a positive definite function on $G$ (see Section \ref{SectionOnMeans}).

It is clear that (ii)$\rightarrow$(i). Then fact that (i)$\rightarrow$(iii) and (iv)$\rightarrow$(v) are a consequence of Theorem \ref{RepresentationTheoremForAmenableGroups}. To see that (v)$\rightarrow$(iv), we will assume familiarity with the Stone-\v{C}ech compactification $\beta G$ of $G$, and refer the reader to \cite{AlgebraInTheSCC} for background. 
For $n \in \mathbb{N}$, let $u:G\rightarrow\mathbb{C}$ be given by $u(g) = u_g$, and let $\tilde{u}:\beta G\rightarrow\mathbb{C}$ be the unique continuous extension of $u$. 
We see that each $\nu_n$ has a unique extension to a probability measure $\tilde{\nu}_n$ on $\beta G$. Let $\mu$ be any probability measure on $(\beta G,\mathscr{A})$ with $\mathscr{A}$ the Borel $\sigma$-algebra that is a weak$^*$ limit of the sequence $\left\{\tilde{\nu}_n\right\}_{n = 1}^\infty$, and let $\left\{\tilde{\nu}_{M_q}\right\}_{q = 1}^\infty$ be a subsequence converging to $\mu$.
Let $\tau_g:\beta G\rightarrow \beta G$ be given by $\tau_g(p) = g^{-1}\cdot p$,\footnote{It is worth noting that we are using different notation than in \cite{AlgebraInTheSCC} since we are assuming that $g^{-1}\cdot p$ is continuous with respect to the variable $p$ instead of the variable $g$. The necessity to do so stems from the fact that we chose to work with left-asymptotically invariant sequences of probability rather than right.}, hence measurable. 
Letting $\mathscr{B}$ be the countably generated $\sigma$-algebra of $\tilde{u}$ and $(\tau_g)_{g \in G}$, we see that $(\beta G,\mathscr{B},(\tau_g)_{g \in G},\mu)$ is isomorphic to a measure preserving system on a standard probability space. Lastly, we see that

\begin{equation}
    \langle \tau_v\tilde{u},\tilde{u}\rangle  = \overline{\langle \tau_{v^{-1}}\tilde{u},\tilde{u}\rangle} = \lim_{q\rightarrow\infty}\int_G\overline{u_{vg}}u_gd\nu_{M_q}\text{ and }\int_{\beta G}\tilde{u}d\mu = \lim_{q\rightarrow\infty}\int_Gu_gd\nu_{M_q}(g).
\end{equation}

It is clear that (iii)$\rightarrow$(v). Now let us show that (v)$\rightarrow$(iii) when $G$ is abelian. We see that if $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ is a measure preserving system and $f \in L^2(X,\mu)$ is normalized so that $||f||_2 = 1$, then $\phi(g) = \langle \tau_gf,f\rangle$ is a positive definite sequence with $\phi(e) = 1$, so there exists a probability measure $\nu$ on $\widehat{G}$ for which $\hat{\nu}(g) = \langle \tau_gf,f\rangle$ and $\nu(\{0\}) = ||P_If||_2^2 \ge \left|\int_Xfd\mu\right|^2$. We may use Lemma \ref{Modulus1RepresentationForAbelianGroups} to obtain a measure preserving system $(Y,\mathscr{A},\mu',(S_g)_{g \in G})$ and a measurable $f':Y\rightarrow S(G)$ satisfying $\phi(g) = \langle S_gf',f'\rangle$ and $\nu(\{0\}) = \int_Yf'd\mu'$.

\label{RemarkAboutCompletingTheListOfEquivalences}
    Now let us consider an example to show why we need the second condition in Equations \eqref{ComplexNumbersSequenceEquation1} and \eqref{HilbertSpaceSequenceEquation1} in Theorem \ref{FvdCIsvdCForAmenableGroups} despite not needing these conditions in Theorem \ref{EquivalentCharacterizationsOfvdC}. 
    Let $G = \mathbb{Z}$ and consider the F\o lner sequence $F_n = [n^3,n^3+2n]$. For $m \in [n^3,n^3+n]$ let $u_m = 1$, let $u_{n^3+2n} = 1$, for $m \in [n^3+2n+1,n^3+3n]$ let $u_m = -n$, and let $u_m = 0$ for all other values of $m$. 
    We see that

    \begin{equation*}
        \lim_{n\rightarrow\infty}\frac{1}{|F_n|}\sum_{m \in F_n}|u_m|^2 = \lim_{n\rightarrow\infty}\frac{1}{|F_n|}\sum_{m \in F_n}u_m = \frac{1}{2}\text{ and }\lim_{n\rightarrow\infty}\frac{1}{|F_n|}\sum_{m \in F_n}u_{m+h}\overline{u_m} = 0\text{ for all }h \in \mathbb{N}.
    \end{equation*}

    Furthermore, in Theorem \ref{FvdCIsvdCForAmenableGroups}, we would like to show that (i)-(iv) are equivalent for any amenable group. This would follow from our proof provided the following questions has a positive answer for all amenable $G$.

\label{MainConjecture}
    Let $G$ be a countable group and let $\phi:G\rightarrow\mathbb{C}$ be a positive definite sequence for which $\phi(e) = 1$. Does there exists a measure preserving system $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ and a measurable $f:X\rightarrow\mathbb{S}^1$ for which the following holds:
    \begin{enumerate}[(i)]
        \item $\phi(h) = \langle \tau_hf,f\rangle$ for all $h \in G$.
        \item $\int_Xfd\mu = 0$ if and only if $f$ is orthogonal to the subspace of $L^2(X,\mu)$ of $T$-invariant functions.
    \end{enumerate}

\label{EquivalentCharacterizationsInCountableGroups}
Let $G$ be a countable discrete group and let $M$ denote the unique mean on the set $W(G)$ of weakly almost periodic functions on $G$. For a set $V \subseteq G\setminus\{e\}$, the following are equivalent:
    \begin{enumerate}[(i)]
        \item \label{item:unitary_inv2} $V$ is a \textbf{set of operatorial recurrence}, i.e., for every unitary representation $\pi$ of $G$ on a Hilbert space $\mathcal{H}_\pi$, and every vector $\xi \in \mathcal{H}_{\pi}$, if $\langle \pi (v)\xi ,\xi \rangle =0$ for all $v\in V$, then $\xi$ is orthogonal to the subspace of $\pi (G)$-invariant vectors.  

        \item \label{item:unitary_approx_inv}
        For every $\epsilon >0$ and every finite set $H \subseteq G$ there is some $\delta >0$ and $F\subseteq V$ finite such that for every unitary representation $\pi$ of $G$ on $\mathcal{H}_\pi$, and every unit vector $\xi \in \mathcal{H}_{\pi}$, if $\sup _{v\in F}|\langle \pi (v)\xi ,\xi \rangle | <\delta$ then $|\langle \xi ,\eta \rangle |<\epsilon$ for every $(\pi (H),\delta )$-invariant unit vector $\eta \in \mathcal{H}_{\pi}$.

        \item\label{GeneralMPSvdC} For any measure preserving system $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ and any $f \in L^2(X,\mu)$ satisfying $\langle \tau_vf,f\rangle\allowbreak = 0$ for all $v \in V$, we have $\int_Xfd\mu = 0$.

        \item\label{GeneralErgodicMPSvdC} For any ergodic measure preserving system $(X,\mathscr{B},\mu,(\tau_g)_{g \in G})$ and any $f \in L^2(X,\mu)$ satisfying $\langle \tau_vf,f\rangle = 0$ for all $v \in V$, we have $\int_Xfd\mu = 0$.

        \item\label{GeneralTrigonometricPolynomialvdC} For any unitary representation $U$ of $G$ on a Hilbert space $\mathcal{H}$ and any $\epsilon > 0$, there exists

        \begin{equation*}
            P \in B(V) := \left\{\sum_{g \in G}c_gU_g\ |\ (c_g)_{g \in G}\text{ has finite support contained in }V\cup V^{-1}\text{ and }\sum_{g \in G}c_g = 1\right\},
        \end{equation*}
        such that $P = P^*$ and $P+\epsilon$ is a positive operator.
        \item\label{Generalpositivedefinitevdc} For any $\epsilon > 0$, there exists a positive definite sequence $(a_g)_{g \in G}$ with finite support contained in $V\cup V^{-1}\cup\{e\}$ satisfying

        \begin{equation}
            \sum_{g \in G}a_g = 1\text{ and }|a_e| < \epsilon.
        \end{equation}

        \item\label{item:GeneralizedUnitary_inv2} For every unitary representation $\pi$ of $G$ on $\mathcal{H}_\pi$, and every vector $\xi \in \mathcal{H}_{\pi}$, if 

        \begin{equation}
            \sum_{v \in V}\left|\langle \pi(v)\xi,\xi\rangle\right| < \infty,
        \end{equation}
        then $\xi$ is orthogonal to the subspace of $\pi (G)$-invariant vectors.   

        \item\label{item:GeneralizedUnitary_invp} For every unitary representation $\pi$ of $G$ on $\mathcal{H}_\pi$, and every vector $\xi \in \mathcal{H}_{\pi}$, if there exists $p \in \mathbb{N}$ for which

        \begin{equation}
            \sum_{v \in V}\left|\langle \pi(v)\xi,\xi\rangle\right|^p < \infty,
        \end{equation}
        then $\xi$ is orthogonal to the subspace of $\pi (G)$-invariant vectors.   

        \item\label{item:GeneralizedWMUnitary_inv2} For every unitary representation $\pi$ of $G$ on $\mathcal{H}_\pi$, and every vector $\xi \in \mathcal{H}_{\pi}$, if there exists $p \in \mathbb{N}$ for which

        \begin{equation}
            \sum_{v \in V}\left|\langle \pi(v)\xi,\xi\rangle\right|^p < \infty,
        \end{equation}
        then $\xi$ is orthogonal to the closed subspace spanned by the finite dimensional subrepresentations of $\pi$.

        \item\label{MeanOnAPFunctionsCharacterization1} If $\phi \in \mathbf{P}(G)$ is such that $\phi(v) = 0$ for all $v \in V$, then $M(\phi) = 0$.

        \item\label{MeanOnAPFunctionsCharacterization2} If $\phi \in \mathbf{P}(G)$ is such that $\sum_{v \in V}|\phi(v)|^p < \infty$ for some $p \in \mathbb{N}$, then $M(|\phi|) = 0$.
    \end{enumerate}
